import{z as B,x as A,o as e,c as m,q as n,j as s,D as E,d as r,s as o,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"布朗运动与路径性质","description":"","frontmatter":{"title":"布朗运动与路径性质","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/brownian-motion-paths.md","filePath":"quant/brownian-motion-paths.md","lastUpdated":1791413859000}'),d={name:"quant/brownian-motion-paths.md"};function _(h,a,p,W,u,D){const i=A("Mermaid");return e(),m("div",null,[a[2]||(a[2]=n('<h1 id="布朗运动与路径性质" tabindex="-1">布朗运动与路径性质 <a class="header-anchor" href="#布朗运动与路径性质" aria-label="Permalink to &quot;布朗运动与路径性质&quot;">​</a></h1><div class="epigraph"><p>布朗运动几乎必然连续，却几乎必然处处不可微；增量独立、平稳、高斯，方差随时间线性增长。</p><footer>—— 据 Karatzas and Shreve, Brownian Motion and Stochastic Calculus, 1991, 第 2 章；Wiener, 1923 整理</footer></div><p>本课是量化栏的第一课，也是「随机分析与金融数学」的第一课。定价数学需要一条连续时间的噪声源：既足够随机，路径又足够规则，后面才能积分、换测度、写复制。本课从路径性质起笔，不从限价簿、不从 Harris 的微观结构起笔。后课默认已经读完本课：标准布朗运动的四条公理、协方差 \\(\\mathrm{Cov}(W_s,W_t)=\\min(s,t)\\)，以及「连续但不可微」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>离散时间里，独立同分布和 \\(S_n=\\sum_{i=1}^n\\xi_i\\) 已经能写随机游走。缺口是连续时间：步长缩到零之后，极限过程 \\(W=\\{W_t\\}_{t\\ge 0}\\) 必须满足哪些<strong>路径级</strong>约束，才既是噪声、又能承载微积分。若样本路径像 \\(C^1\\) 那样光滑，二次变差会消失，伊藤修正没有着落；若路径不连续，后课的伊藤积分与 Black–Scholes PDE 都要另起。本课只钉连续情形的标准对象。</p><p>连续、独立增量、高斯——三条不能互相替代。只连续可以是确定性函数；只独立增量可以是复合泊松。主干要的是：连续路径上的高斯噪声，方差按日历时间线性累积。</p><p><span class="marginnote">数字体会 \\(\\mathrm{Var}(W_t)=t\\)：以「天」为单位、单日方差取 \\(1\\)，则 \\(10\\) 天后方差是 \\(10\\)、标准差约 \\(3.2\\)；\\(252\\) 个交易日后方差 \\(252\\)、标准差约 \\(15.9\\)。标准差按 \\(\\sqrt{t}\\) 增长——时间翻 4 倍，典型位移只翻 2 倍。这是后课 \\(\\sigma\\sqrt{\\Delta t}\\) 的直觉底子。</span></p><h3 id="布朗运动不是从订单流推出来的" tabindex="-1">布朗运动不是从订单流推出来的 <a class="header-anchor" href="#布朗运动不是从订单流推出来的" aria-label="Permalink to &quot;布朗运动不是从订单流推出来的&quot;">​</a></h3><p>\\(W\\) 是外生噪声，不是成交价的估计量。Bachelier 1900 与 Einstein 1905 把扩散和随机游走连起来，Wiener 给出测度；后课把股价写成 \\(W\\) 的函数，并不表示 \\(W\\) 来自微观结构。微观结构是另一棵树，本课程不重写。</p><p><span class="marginnote">\\(\\mathrm{Var}(W_t)=t\\) 把时间单位钉进方差。换时间尺度，增量方差按比例缩放，这是后课 GBM 里 \\(\\sigma\\sqrt{\\Delta t}\\) 的来源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>概率空间 \\((\\Omega,\\mathcal F,\\mathbb P)\\) 上，<strong>标准布朗运动</strong>满足：(i) \\(W_0=0\\)；(ii) 不相交区间上增量独立；(iii) \\(W_t-W_s\\sim\\mathcal N(0,t-s)\\)；(iv) 存在连续修正。由此 \\(\\mathbb E[W_t]=0\\)，\\(\\mathrm{Var}(W_t)=t\\)，\\(\\mathrm{Cov}(W_s,W_t)=\\min(s,t)\\)。平稳性：\\(W_{s+t}-W_s\\) 与 \\(W_t\\) 同分布。马尔可夫性：给定 \\(W_s\\)，未来只通过当前值依赖过去。</p><p>几乎必然，路径在任意区间上处处不可微，全变差无穷。这不是病态附录，而是下一课二次变差的前提：一阶变差炸掉，平方变差收敛到 \\(t\\)。</p>',13)),(e(),s(l,null,{default:E(()=>[o(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20AX%5B%22%E5%9B%9B%E6%9D%A1%E5%85%AC%E7%90%86%22%5D%20--%3E%20CONT%5B%22%E5%87%A0%E4%B9%8E%E5%BF%85%E7%84%B6%E8%BF%9E%E7%BB%AD%22%5D%0A%20%20AX%20--%3E%20GAUSS%5B%22%E7%8B%AC%E7%AB%8B%E9%AB%98%E6%96%AF%E5%A2%9E%E9%87%8F%22%5D%0A%20%20CONT%20--%3E%20ROUGH%5B%22%E5%A4%84%E5%A4%84%E4%B8%8D%E5%8F%AF%E5%BE%AE%E3%80%81%E5%85%A8%E5%8F%98%E5%B7%AE%E6%97%A0%E7%A9%B7%22%5D%0A%20%20GAUSS%20--%3E%20VAR%5B%22%E6%96%B9%E5%B7%AE%E7%AD%89%E4%BA%8E%E6%97%A5%E5%8E%86%E6%97%B6%E9%97%B4%22%5D%0A%20%20ROUGH%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E4%BA%8C%E6%AC%A1%E5%8F%98%E5%B7%AE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[t("span",{class:"marginnote"},"「几乎必然」翻译过来就是「概率为 1」：例外路径可能存在，但它们的总概率为零。「处处不可微」的直觉是拿放大镜看路径——无论放大多少倍，看到的仍是同样细密的锯齿，任何一点都找不到光滑切线；对比圆或抛物线，放大够了局部就是直线。")],-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"高斯增量把有限维分布钉死：\\((W_{t_1},\\ldots,W_{t_n})\\) 是均值为零、协方差为 \\(\\min(t_i,t_j)\\) 的多元正态。Kolmogorov 连续性准则保证存在 Hölder 指数小于 \\(1/2\\) 的连续修正——刚好不够可微，刚好够连续。Levy 模连续性把粗糙程度定量化；本课只需记住：粗糙由二次变差刻画，不是由全变差。平移与缩放：\\(a^{-1/2}W_{at}\\) 仍是标准布朗运动。后课换到期、换步长，噪声归一化都走这条自相似性。马尔可夫性让价格函数可以只依赖 \\((t,W_t)\\) 或 \\((t,S_t)\\)，而不必记住整条路径——路径依赖合约是后课才打开的缺口。",-1)),(e(),s(l,null,{default:E(()=>[o(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20RW%5B%22%E7%A6%BB%E6%95%A3%E9%9A%8F%E6%9C%BA%E6%B8%B8%E8%B5%B0%EF%BC%9A%E5%8F%8D%E5%A4%8D%E6%8E%B7%E7%A1%AC%E5%B8%81%E7%B4%AF%E5%8A%A0%22%5D%20--%3E%20SMALL%5B%22%E6%AD%A5%E9%95%BF%E4%B8%8E%E6%97%B6%E9%97%B4%E9%97%B4%E9%9A%94%E4%B8%80%E8%B5%B7%E7%BC%A9%E5%B0%8F%22%5D%0A%20%20SMALL%20--%3E%20SCALE%5B%22%E6%AD%A5%E9%95%BF%E6%8C%89%E9%97%B4%E9%9A%94%E7%9A%84%E5%B9%B3%E6%96%B9%E6%A0%B9%E7%BC%A9%E6%94%BE%22%5D%0A%20%20SCALE%20--%3E%20LIM%5B%22%E6%9E%81%E9%99%90%E8%B7%AF%E5%BE%84%22%5D%0A%20%20LIM%20--%3E%20CONT%5B%22%E8%BF%9E%E7%BB%AD%22%5D%0A%20%20LIM%20--%3E%20ROUGH%5B%22%E5%A4%84%E5%A4%84%E4%B8%8D%E5%8F%AF%E5%BE%AE%22%5D%0A%20%20CONT%20--%3E%20BM%5B%22%E6%A0%87%E5%87%86%E5%B8%83%E6%9C%97%E8%BF%90%E5%8A%A8%20W%22%5D%0A%20%20ROUGH%20--%3E%20BM%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">初学者容易以为「连续的函数大体都该可微」。日常经验如此，对布朗路径不成立：连续只保证路径不断开，不保证斜率存在。这一步想错，后面就会顺手写出 \\((\\mathrm dW)^2=0\\)，丢掉伊藤修正——下一课的二次变差正是为堵这个漏洞准备的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不构造 Wiener 测度，不证不变原理，不引入分数布朗或带跳过程。伊藤积分、SDE、风险中性都还没出场。后课默认：\\(W\\) 已是标准布朗运动；写 \\(\\mathrm d W\\) 时，默认独立高斯增量与连续路径。下一课<a href="/quant/quadratic-variation">二次变差</a>回答：在不可微路径上，乘法规则用什么替代 \\((\\mathrm d W)^2=0\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>量化栏从路径噪声起笔：标准布朗运动是后面积分与定价的外生源。</li><li>独立平稳高斯增量、连续路径、\\(\\mathrm{Var}(W_t)=t\\)。</li><li>几乎必然处处不可微、全变差无穷；二次变差留给下一课。</li><li>\\(W\\) 不是限价簿对象，本课程不重写微观结构。</li><li>后课默认本课已读完。</li><li>出处：Karatzas–Shreve 第 2 章；Wiener 1923。</li></ul>',5))])}const b=B(d,[["render",_]]);export{C as __pageData,b as default};
